EMBLEM_B64 = ""

LOGO_URI = "data:image/webp;base64," + LOGO_B64
EMBLEM_URI = "data:image/png;base64," + EMBLEM_B64


def emblem_file() -> str:
    """Écrit l'emblème dans un fichier temporaire (requis pour l'avatar du chat)."""
    path = Path(tempfile.gettempdir()) / "qanoun_ma_emblem.png"
    if not path.exists():
        path.write_bytes(base64.b64decode(EMBLEM_B64))
    return str(path)


EMBLEM_PATH = emblem_file()

