def create_conversation() -> None:
    """Créer une conversation vide dans la session Streamlit."""
    identifier = uuid4().hex
    st.session_state["conversations"][identifier] = {
        "title": "Nouvelle conversation",
        "messages": [],
    }
    st.session_state["active_conversation"] = identifier


def initialize_state() -> None:
    if "conversations" not in st.session_state:
        st.session_state["conversations"] = {}
    if "active_conversation" not in st.session_state:
        create_conversation()


def active_conversation() -> dict:
    return st.session_state["conversations"][st.session_state["active_conversation"]]


def go_home() -> None:
    """Revenir à l'accueil : une conversation vide, les autres sont conservées."""
    if active_conversation()["messages"]:
        create_conversation()


def delete_conversation(identifier: str) -> None:
    """Supprimer une conversation ; en ouvrir une autre si besoin."""
    conversations = st.session_state["conversations"]
    conversations.pop(identifier, None)
    if not conversations:
        create_conversation()
    elif st.session_state["active_conversation"] not in conversations:
        st.session_state["active_conversation"] = list(conversations)[-1]


def ask_qanoun(question: str) -> None:
    """Rechercher les passages et générer une réponse avec monitoring."""
    thread = active_conversation()
    thread["messages"].append({"role": "user", "content": question})

    if thread["title"] == "Nouvelle conversation":
        short_title = " ".join(question.strip().split())
        thread["title"] = short_title[:43] + ("…" if len(short_title) > 43 else "")

    try:
        with st.spinner("Mistral 7B prépare la réponse…"):
            passages = retrieve(question, allowed_access={"public"})
            result = generate_with_monitoring(question, passages)
    except Exception:
        LOGGER.exception("Échec du pipeline RAG")
        result = {
            "status": "error",
            "answer": "Une erreur technique est survenue. Vérifie l'index ChromaDB et Ollama.",
            "sources": [],
        }

    thread["messages"].append({
        "role": "assistant",
        "content": result["answer"],
        "status": result["status"],
        "sources": result.get("sources", []),
    })


def display_message(message: dict) -> None:
    avatar = "👤" if message["role"] == "user" else EMBLEM_PATH
    with st.chat_message(message["role"], avatar=avatar):
        if message["role"] == "user":
            st.markdown(message["content"])
            return

        status = message.get("status", "ok")
        if status == "ok":
            st.markdown(message["content"])
        elif status == "insufficient_context":
            st.warning(message["content"])
        else:
            st.error(message["content"])

        sources = message.get("sources", [])
        if sources:
            with st.expander(f"📚 Passages fournis ({len(sources)})"):
                for source in sources:
                    st.write(f"[{source['reference']}] {source['source']}")
                    page = source.get("page")
                    distance = source.get("distance")
                    st.caption(
                        f"Page : {page if page is not None else 'non disponible'}"
                        + (f" · Distance : {distance}" if distance is not None else "")
                    )
                st.caption(
                    "Passages transmis au modèle, sans vérification automatique "
                    "de leur utilisation effective dans la réponse."
                )


initialize_state()

# --------- Barre latérale : logo et navigation entre conversations ---------
with st.sidebar:
    st.markdown(
        f'<div class="ml-side-logo"><img src="{LOGO_URI}" alt="Qanoun.ma"></div>',
        unsafe_allow_html=True,
    )
    st.caption("Assistant documentaire · Mistral 7B local")

    if st.button("＋  Nouvelle conversation", use_container_width=True, type="primary"):
        go_home()
        st.rerun()

    st.divider()
    st.markdown("**Conversations**")
    for identifier, conversation in reversed(list(st.session_state["conversations"].items())):
        is_active = identifier == st.session_state["active_conversation"]
        label = ("● " if is_active else "💬 ") + conversation["title"]
        row_select, row_menu = st.columns([6, 1], gap="small")
        with row_select:
            if st.button(label, key=f"select_{identifier}", use_container_width=True):
                st.session_state["active_conversation"] = identifier
                st.rerun()
        with row_menu:
            with st.popover("⋮", use_container_width=True):
                st.caption("Supprimer cette conversation ?")
                if st.button(
                    "🗑️ Supprimer",
                    key=f"delete_{identifier}",
                    type="primary",
                    use_container_width=True,
                ):
                    delete_conversation(identifier)
                    st.rerun()

    st.divider()
    st.caption("ENSA Fès · ISDIA3 · MLOps 2026–2027")
    st.caption("Chaibi Douae & Amiri Abdelhadi")

